:root{--bg:#080908;--paper:#f1eee7;--ink:#f5f2ec;--muted:#9a9d98;--line:#2a2d29;--green:#65bc86;--ease:cubic-bezier(.16,1,.3,1)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:"Helvetica Neue",Helvetica,Arial,sans-serif;overflow-x:hidden}a{color:inherit;text-decoration:none}.wrap{width:min(1360px,calc(100% - 64px));margin:auto}.nav{height:78px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);position:relative;z-index:5}.nav img{width:125px}.navlinks{display:flex;gap:24px;font-size:12px}.btn{display:inline-flex;gap:12px;align-items:center;border:1px solid #444;padding:14px 18px;font-size:12px}.btn.green{background:var(--green);color:#06110b;border-color:var(--green)}.hero{min-height:calc(100vh - 78px);display:grid;grid-template-rows:auto 1fr auto;padding:46px 0 28px}.kicker{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--green)}.hero h1{font-size:clamp(70px,10.2vw,176px);line-height:.83;letter-spacing:-.075em;margin:8vh 0 0;max-width:1200px}.hero h1 .outline{-webkit-text-stroke:1px var(--green);color:transparent}.hero-foot{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:end}.hero-copy{max-width:600px;font-size:20px;line-height:1.42;color:#c7cbc5}.hero-meta{justify-self:end;display:grid;grid-template-columns:repeat(3,auto);gap:28px;font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:#949993}.hero-meta b{display:block;color:var(--ink);font-weight:500;margin-top:6px}.green-band{background:var(--green);color:#07100a;padding:110px 0}.green-band h2{font-size:clamp(54px,8vw,126px);line-height:.9;letter-spacing:-.065em;margin:0;max-width:1300px}.green-band p{font-size:22px;line-height:1.45;max-width:630px;margin:42px 0 0 48%}.case-intro{padding:150px 0}.intro-grid{display:grid;grid-template-columns:.7fr 1.3fr;gap:80px}.num{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--green)}.intro-grid h2{font-size:clamp(46px,6vw,90px);line-height:.96;letter-spacing:-.055em;margin:0 0 32px}.intro-grid p{font-size:19px;line-height:1.55;color:#b9bdb7;max-width:760px}.system{padding:0 0 170px}.system-head{display:flex;justify-content:space-between;gap:40px;align-items:end;margin-bottom:54px}.system-head h2{font-size:clamp(42px,5vw,76px);line-height:.98;letter-spacing:-.05em;margin:0;max-width:840px}.system-head p{max-width:420px;color:#a7aba5;line-height:1.5}.story{height:360vh;position:relative}.story-sticky{position:sticky;top:88px;height:calc(100vh - 110px);display:grid;grid-template-columns:1.1fr .9fr;gap:70px;align-items:center}.browser{background:#eef1eb;color:#0b0f0c;border:1px solid #4c514b;min-height:620px;position:relative;overflow:hidden}.browserbar{height:44px;border-bottom:1px solid #d4d9d1;display:flex;align-items:center;gap:7px;padding:0 15px}.dot{width:7px;height:7px;border-radius:50%;background:#c1c6bf}.sitehead{height:72px;background:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 30px;border-bottom:1px solid #dde1dc}.brand4{font-size:24px;font-weight:700;letter-spacing:-.04em}.brand4 span{color:#49a970}.sitehead small{font-size:10px;color:#677068}.pageview{position:absolute;left:0;right:0;top:116px;bottom:0;padding:46px 44px;background:#f5f6f2;opacity:0;transform:translateY(18px);transition:none;visibility:hidden}.pageview.active{opacity:1;transform:none;visibility:visible;animation:revealIn .48s var(--ease)}.pageview .eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:.16em;color:#4e9d68}.pageview h3{font-size:clamp(36px,4vw,65px);line-height:.96;letter-spacing:-.05em;margin:18px 0 18px;max-width:720px}.pageview p{font-size:15px;line-height:1.5;color:#5a625b;max-width:580px}.ui-row{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:28px}.ui-box{background:#fff;border:1px solid #d7dbd5;padding:16px}.ui-box b{display:block;font-size:12px;margin-bottom:5px}.ui-box span{font-size:11px;color:#697069}.lawlist{margin-top:26px;border-top:1px solid #cbd0c9}.lawitem{display:flex;justify-content:space-between;padding:15px 0;border-bottom:1px solid #cbd0c9;font-size:12px}.appointment{margin-top:30px;background:#0d1711;color:#fff;padding:24px;display:flex;justify-content:space-between;align-items:center}.appointment strong{font-size:22px}.copy-stage{position:relative;min-height:440px}.copy{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;opacity:0;visibility:hidden;transform:translateY(24px);transition:none}.copy.active{opacity:1;visibility:visible;transform:none;animation:revealIn .48s var(--ease)}.copy .step{font-size:11px;letter-spacing:.17em;text-transform:uppercase;color:var(--green);margin-bottom:26px}.copy h3{font-size:clamp(48px,5vw,78px);line-height:.95;letter-spacing:-.055em;margin:0 0 24px}.copy p{font-size:18px;line-height:1.52;color:#b4b8b2;max-width:560px}.mobile-story{display:none}.proof{background:var(--paper);color:#121412;padding:140px 0}.proof-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:80px}.proof h2{font-size:clamp(50px,6.5vw,98px);line-height:.92;letter-spacing:-.06em;margin:0}.proof-list{border-top:1px solid #bbbdb8}.proof-row{display:grid;grid-template-columns:60px 1fr;gap:20px;padding:26px 0;border-bottom:1px solid #bbbdb8}.proof-row b{font-size:12px;color:#32925a}.proof-row h3{font-size:28px;margin:0 0 8px;letter-spacing:-.03em}.proof-row p{margin:0;color:#60645f;line-height:1.45}.legal{padding:150px 0}.legal-grid{display:grid;grid-template-columns:1fr 1fr;gap:90px;align-items:start}.legal h2{font-size:clamp(50px,6vw,90px);line-height:.94;letter-spacing:-.055em;margin:0}.legal-copy p{font-size:19px;line-height:1.55;color:#b6bab4}.quote{margin-top:42px;border-left:2px solid var(--green);padding-left:24px;font-size:30px;line-height:1.25;letter-spacing:-.03em}.live{padding:140px 0;background:#0d120f}.live-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:70px;align-items:center}.live-grid>*{min-width:0}.live-panel h3,.live-copy h2{overflow-wrap:anywhere;hyphens:auto}.live-panel{background:#f3f5f0;color:#101510;padding:48px;min-height:500px;display:flex;flex-direction:column;justify-content:space-between}.live-panel .brand4{font-size:38px}.live-panel h3{font-size:54px;line-height:.98;letter-spacing:-.05em;max-width:650px}.live-copy h2{font-size:clamp(48px,5.5vw,82px);line-height:.95;letter-spacing:-.055em;margin:0 0 28px}.live-copy p{color:#aeb4ad;line-height:1.55;font-size:18px}.next{padding:110px 0}.next a{display:flex;justify-content:space-between;align-items:end;border-top:1px solid var(--line);padding-top:34px}.next h2{font-size:clamp(50px,7vw,110px);letter-spacing:-.06em;margin:10px 0 0}.next .arrow{font-size:52px;color:var(--green)}footer{border-top:1px solid var(--line);padding:28px 0 45px;color:#767b75;font-size:11px}.footerin{display:flex;justify-content:space-between}
@keyframes revealIn{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
@media(max-width:1050px){.live-grid{grid-template-columns:1fr;gap:42px}.live-panel{min-height:420px}}
@media(max-width:900px){.wrap{width:min(100% - 36px,760px)}.navlinks{display:none}.hero{min-height:auto;padding-bottom:60px}.hero h1{margin:70px 0 70px;font-size:clamp(64px,15vw,118px)}.hero-foot{grid-template-columns:1fr}.hero-meta{justify-self:start;grid-template-columns:repeat(3,1fr);width:100%}.green-band{padding:80px 0}.green-band p{margin:35px 0 0;max-width:700px}.case-intro{padding:100px 0}.intro-grid,.proof-grid,.legal-grid,.live-grid{grid-template-columns:1fr;gap:42px}.system{padding-bottom:100px}.system-head{display:block}.system-head p{margin-top:22px}.story{display:none}.mobile-story{display:grid;gap:70px}.mobile-pair{display:grid;gap:22px}.mobile-pair .browser{min-height:520px}.mobile-pair .copy{position:static;opacity:1;visibility:visible;transform:none;min-height:auto}.proof{padding:100px 0}.legal{padding:100px 0}.live{padding:100px 0}.live-panel{min-height:420px}.footerin{gap:20px;flex-direction:column}.next{padding:80px 0}.next a{align-items:center}}
@media(max-width:520px){.wrap{width:calc(100% - 28px)}.nav{height:68px}.nav img{width:108px}.hero h1{font-size:16vw;line-height:.87;letter-spacing:-.065em}.hero-copy{font-size:17px}.hero-meta{grid-template-columns:1fr;gap:12px}.green-band h2{font-size:14.5vw}.green-band p{font-size:18px}.case-intro{padding:78px 0}.intro-grid h2{font-size:13vw}.system-head h2{font-size:12vw}.mobile-pair .browser{min-height:455px}.pageview{padding:30px 24px}.pageview h3{font-size:9.5vw}.ui-row{grid-template-columns:1fr}.copy h3{font-size:12vw}.copy p{font-size:16px}.proof h2,.legal h2,.live-copy h2{font-size:12vw}.proof-row{grid-template-columns:42px 1fr}.proof-row h3{font-size:23px}.quote{font-size:25px}.live-panel{padding:28px;min-height:350px}.live-panel h3{font-size:10vw}.next h2{font-size:14vw}.next .arrow{font-size:34px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}

/* REAL WEBSITE ASSET PASS */
.real-site-showcase{--case:#e81848;background:#0a0a0a;color:#f3efe9;padding:clamp(90px,10vw,160px) 0;border-top:1px solid rgba(255,255,255,.09);border-bottom:1px solid rgba(255,255,255,.09)}
.real-site-shell{width:min(1480px,100%);margin:0 auto;padding:0 clamp(20px,4vw,68px)}
.real-site-head{display:grid;grid-template-columns:minmax(0,1.18fr) minmax(280px,.62fr);gap:clamp(34px,7vw,100px);align-items:end;margin-bottom:clamp(42px,5vw,72px)}
.real-site-kicker{display:block;color:var(--case);font-size:10px;letter-spacing:.18em;text-transform:uppercase;margin-bottom:18px}
.real-site-head h2{font-size:clamp(48px,6.4vw,104px);line-height:.9;letter-spacing:-.065em;font-weight:520;margin:0;max-width:980px}
.real-site-head p{margin:0;color:#aaa59e;font-size:clamp(16px,1.15vw,19px);line-height:1.55;max-width:520px}
.real-site-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(16px,2vw,28px)}
.real-site-card{display:block;color:inherit;text-decoration:none;min-width:0;background:#101010;border:1px solid rgba(255,255,255,.14);border-radius:6px;overflow:hidden;transition:transform .6s cubic-bezier(.16,1,.3,1),border-color .4s ease}
.real-site-card:hover{transform:translateY(-5px);border-color:color-mix(in srgb,var(--case) 60%,#fff 10%)}
.real-browser-bar{height:42px;background:#0c0c0c;border-bottom:1px solid rgba(255,255,255,.1);display:flex;align-items:center;gap:6px;padding:0 13px;overflow:hidden}
.real-browser-bar i{width:7px;height:7px;border-radius:50%;background:#383838;flex:0 0 auto}
.real-browser-bar span{margin-left:8px;color:#77736d;font-size:9px;letter-spacing:.08em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.real-shot{position:relative;aspect-ratio:16/10;overflow:hidden;background:#141414}
.real-shot img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:top center;opacity:0;transform:scale(1.01);transition:opacity .45s ease,transform 1.1s cubic-bezier(.16,1,.3,1)}
.real-shot.loaded img{opacity:1}
.real-site-card:hover .real-shot.loaded img{transform:scale(1.035)}
.real-fallback{position:absolute;inset:0;padding:clamp(22px,3vw,42px);display:flex;flex-direction:column;justify-content:space-between;background:linear-gradient(145deg,#111,#171717);z-index:0}
.real-fallback:before{content:"";position:absolute;left:0;top:0;width:4px;height:100%;background:var(--case);opacity:.85}
.real-fallback small{font-size:9px;letter-spacing:.18em;text-transform:uppercase;color:#7c7872}
.real-fallback strong{font-size:clamp(32px,4.2vw,68px);line-height:.9;letter-spacing:-.055em;font-weight:520;max-width:620px;overflow-wrap:anywhere;hyphens:auto}
.real-fallback strong span{color:var(--case)}
.real-caption{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;align-items:end;padding:20px 20px 22px;border-top:1px solid rgba(255,255,255,.08)}
.real-caption strong{display:block;font-size:20px;letter-spacing:-.025em;font-weight:500;margin-bottom:4px}
.real-caption span{display:block;color:#8c8881;font-size:12px;line-height:1.45}
.real-caption b{font-size:18px;color:var(--case);font-weight:400}
.real-site-card--hero{grid-column:1/-1}
.real-site-card--hero .real-shot{aspect-ratio:2.05/1}
.real-site-card--single{grid-column:1/-1}
.real-site-card--single .real-shot{aspect-ratio:2/1}
@media(max-width:900px){.real-site-head{grid-template-columns:1fr;gap:24px}.real-site-grid{grid-template-columns:1fr}.real-site-card--hero,.real-site-card--single{grid-column:auto}.real-site-card--hero .real-shot,.real-site-card--single .real-shot,.real-shot{aspect-ratio:16/10}}
@media(max-width:520px){.real-site-showcase{padding:78px 0}.real-site-shell{padding:0 14px}.real-site-head h2{font-size:12.5vw}.real-caption{padding:16px}.real-caption strong{font-size:18px}.real-fallback strong{font-size:clamp(30px,8.6vw,44px);line-height:.9}}
@media(prefers-reduced-motion:reduce){.real-site-card,.real-shot img{transition:none!important}.real-site-card:hover,.real-site-card:hover .real-shot.loaded img{transform:none!important}}


/* AROZ R3: Documented static editorial case artwork, not third-party website screenshots. */
.case-static-shot{background:radial-gradient(circle at 93% 8%,color-mix(in srgb,var(--case) 12%,transparent),transparent 47%),#111}
.case-static-shot .real-fallback{background:linear-gradient(140deg,#101012 0%,#1a181b 70%,#151215 100%);isolation:isolate}
.case-static-shot .real-fallback small{font-size:clamp(11px,1vw,13px)!important;color:#c9bebd;letter-spacing:.1em}
.case-static-shot .real-fallback strong{font-weight:520;letter-spacing:-.06em;max-width:85%}
.case-original-art .case-static-shot{background-image:linear-gradient(92deg,rgba(7,7,10,.94),rgba(7,7,10,.21)),radial-gradient(circle at 82% 24%,#276c45 1%,transparent 60%);background-size:cover;background-position:center}
.case-original-art .case-static-shot .real-fallback{background:linear-gradient(90deg,rgba(5,5,8,.8) 0%,rgba(5,5,8,.25) 66%,rgba(5,5,8,.2));}
.case-original-art .case-static-shot .real-fallback strong{color:#fff;text-shadow:0 2px 9px rgba(0,0,0,.45)}
@media(max-width:520px){.case-static-shot .real-fallback{padding:22px!important}.case-static-shot .real-fallback strong{font-size:clamp(28px,7.2vw,44px)!important;max-width:95%;line-height:1.02}}
@media(prefers-reduced-motion:reduce){.real-site-card{transition:none!important}.real-site-card:hover{transform:none!important}}

/* AROZ R2 – detail craft / accessibility; scoped additions only. */
html { scroll-padding-top: 90px; }
:where(h1,h2,h3) { text-wrap: balance; }
:where(p,li,dd) { overflow-wrap: break-word; }
:where(a, button, input, select, textarea):focus-visible { outline: 2px solid #ff4164; outline-offset: 4px; box-shadow: 0 0 0 2px rgba(0,0,0,.5); }
:where(button, input, textarea, select) { font: inherit; }
:where(img) { max-width:100%; }
@media(prefers-reduced-motion:reduce){ html{scroll-behavior:auto!important} *,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important} }
@media(max-width:620px){
 :where(h1,h2,h3) { hyphens:auto; overflow-wrap:normal; }
 :where(p) { line-height:1.55; }
 :where(a,button) { -webkit-tap-highlight-color:transparent; }
}

/* Typography AA craft floor for legacy 8-10px labels */
.sitehead small{font-size:12px!important}
.pageview .eyebrow{font-size:12px!important}
.real-site-kicker{font-size:12px!important}
.real-browser-bar span{font-size:12px!important}
.real-fallback small{font-size:12px!important}


/* P1: primary case metadata legible; preserve page-specific color palette. */
@media(max-width:820px){
 :where(.hero h1){line-height:1.01;overflow-wrap:normal}
 :where(.hero-lede, .case-intro p, .challenge-copy p){line-height:1.55}
}

/* Reduce dead air while preserving the original typographic character. */
@media (min-width: 901px) { .hero.wrap { min-height:0; grid-template-rows:auto auto auto; row-gap:clamp(44px,5vw,86px); padding-bottom:65px; } .hero h1 {margin:0;} }
.hero .outline {color:rgba(101,188,134,.3);-webkit-text-stroke:1.35px #82dba5;}
.hero-copy {max-width: 660px;}
@media (max-width:520px){.hero .outline{-webkit-text-stroke:1px #90e0af;color:rgba(101,188,134,.12)}}

.r11-skip{position:fixed;z-index:99999;top:9px;left:12px;padding:12px 17px;border:2px solid #fff;background:#101014;color:#fff;font:700 15px/1.25 Arial,sans-serif;text-decoration:none;transform:translateY(-160%)}
.r11-skip:focus-visible{transform:none;outline:3px solid #ff4164;outline-offset:3px}
